"""Conversion binary -> decimal. Needed to calculate
    decimal variable value from binary coded genome."""
def bin_dec(bin: Any) -> object {
    dec = 0.0;
    bin.reverse();
    for i in range(0, len(bin)) {
        dec += bin[i] * (2 ** i);
    }
    return dec;
}

"""
    Returns element at index or default
    :param obj: list
    :param idx: index
    :param dft: default value
    :return: element
    """
def get_list_elem(`obj: Any, idx: Any, dft: Any) -> object {
    if ((len(`obj) - 1) < idx) {
        return dft;
    }
    return `obj[idx];
}
